css:
.gh { width: min(900px, 100%); padding: 24px; }
.gh-titulo { margin: 0 0 16px; font-family: 'Sora', sans-serif; font-size: 18px; }
.gh-titulo-2 { margin-top: 40px; }

/* O container desenha duas bordas, a célula desenha as outras duas: nenhum
   encontro soma 2px e a malha fica regular contra a borda externa. */
.gh-grade {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(240px, 1fr));
  border-top: 1px solid var(--border);
  border-left: 1px solid var(--border);
}
.gh-cel {
  /* min-width: 0 é o que faz texto longo quebrar em vez de estourar a coluna. */
  min-width: 0;
  padding: 20px;
  border-right: 1px solid var(--border);
  border-bottom: 1px solid var(--border);
}
.gh-cel strong { display: block; font-size: 14px; margin-bottom: 4px; }
.gh-cel span { font-size: 13px; color: var(--text-muted); line-height: 1.5; }

/* flex-wrap com largura calculada, não grid: numa grade rígida o item que não
   fecha a última linha deixa célula vazia COM BORDA no fim da parede. */
.gh-logos { --gap: 12px; display: flex; flex-wrap: wrap; gap: var(--gap); }
.gh-logo {
  width: calc((100% - 2 * var(--gap)) / 3);
  display: grid; place-items: center;
  padding: 20px 8px;
  border: 1px solid var(--border); border-radius: 8px;
  font-family: 'JetBrains Mono', monospace; font-size: 11px; letter-spacing: 0.1em;
  color: var(--text-muted);
  opacity: 0.8;
  transition: opacity 0.2s ease, border-color 0.2s ease;
}
.gh-logo:hover { opacity: 1; border-color: var(--accent); }

@media (min-width: 640px) { .gh-logo { width: calc((100% - 3 * var(--gap)) / 4); } }
@media (min-width: 1024px) { .gh-logo { width: calc((100% - 5 * var(--gap)) / 6); } }
